from crewai import Agent
from config import VERBOSE, EVALUATOR_MODEL, MODEL_PROVIDER

# create an agent for evaluating the answer generated by the generator agent
evaluator_agent = Agent(
    # set the role
    role="RAG Quality Evaluator",

    # set the goal
    goal="""
        Evaluate RAG answers for factual grounding, relevance,
        completeness, citation quality, and hallucination.
    """,

    # set the backstory
    backstory="""
        You are an expert RAG evaluator. 
        You compare generated answers against the retrieved context. 
        You never assume information is correct simply because it sounds plausible. 
        Every factual claim must be supported by the supplied context.
    """,

    verbose=VERBOSE,

    llm=f"{MODEL_PROVIDER}/{EVALUATOR_MODEL}"
)